def set_group_owners(apps, schema_editor):
    """v2.1 L3: the person who started each existing group becomes its owner."""
    Thread = apps.get_model("messaging", "Thread")
    Participant = apps.get_model("messaging", "ThreadParticipant")
    for thread_id, creator_id in Thread.objects.filter(thread_type="group", created_by__isnull=False) \
            .values_list("id", "created_by_id").iterator():
        Participant.objects.filter(thread_id=thread_id, user_id=creator_id).update(role="owner")
    # Groups whose creator is gone: the longest-standing member owns it.
    for thread_id in Thread.objects.filter(thread_type="group").values_list("id", flat=True).iterator():
        rows = Participant.objects.filter(thread_id=thread_id)
        if not rows.filter(role__in=("owner", "admin")).exists():
            first = rows.order_by("joined_at", "id").first()
            if first is not None:
                Participant.objects.filter(pk=first.pk).update(role="owner")


